  ('gaestebuch', (SELECT MAX(id) FROM comments), 'Frank', NULL, 'Hi Larry, altes Haus! Wie viel Jahre ist das her, dass wir uns mehrmals im Jahr in den heiligen Luxemburger Hallen trafen? Ich beneide dich heute noch für euren Auftritt vor Michael Jackson... mit Mundschutz... Viele Grüße nach LUX', '2018-07-24', 'year', 'approved', 0, 'wix');
