INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES
  ('gaestebuch', NULL, 'claus-Dieter ruf (Doctor)', NULL, 'Vorschlag von mir: Macht doch ein Reunion-Konzert von Scaramouche im Schlachthof, und den Eintritt nehmt ihr zur Finanzierung. Der Laden wird mit Sicherheit voll. Habe früher alle Konzerte mitgenommen. Kenne Marc und Gert schon lange, bin selber Musiker.', '2019-07-24', 'year', 'approved', 0, 'wix');
