INSERT INTO comments (page, parent_id, name, ort, body, created_at, date_precision, status, is_team, source) VALUES
  ('gaestebuch', (SELECT MAX(id) FROM comments), 'Maik', NULL, 'Hallo, das tut uns leid – und die Frage ist berechtigt, wenn plötzlich etwas fehlt. Absichtlich gelöscht haben wir nichts. Die Seite ist gerade frisch umgezogen, weg vom alten Anbieter, und dabei sind Beiträge auf der Strecke geblieben, die wir jetzt Stück für Stück zurückholen. Wenn du weißt, welcher Beitrag fehlt, schreib es uns kurz – dann suchen wir gezielt danach. Danke, dass du nachgefragt hast.', '2026-09-29', 'exact', 'approved', 1, 'manual');
